-- 106_room_rpc_member_guards.sql
-- Generated by TARS from LIVE pg_proc (2026-10-23), applied live on Nathan's approval ("fix it").
-- 1. Helpers is_room_member + rpc_caller_trusted.
-- 2. Room/event readers + 2 small writes: original renamed to <name>__inner (no grants),
--    same-signature wrapper checks active membership, then delegates. Bodies untouched.
--    get_casino_config returns vision_api_key to hosts only.
-- 3. Seven RPCs no shipped build calls: EXECUTE revoked from app roles (service_role kept).
-- 4. Three created_by host checks -> is_room_host (promoted hosts were locked out).
begin;

create or replace function public.is_room_member(p_room_id uuid, p_user_id uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.room_memberships
                  where room_id = p_room_id and user_id = p_user_id
                    and membership_status = 'active');
$$;
revoke all on function public.is_room_member(uuid, uuid) from public, anon;
grant execute on function public.is_room_member(uuid, uuid) to authenticated, service_role;

-- Trusted = no JWT at all (pg_cron, triggers, SQL console) or the service role
-- (edge functions). Every PostgREST call carries verified claims, which a client
-- cannot set, so an app user can never be "trusted".
create or replace function public.rpc_caller_trusted()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::json->>'role'
         is distinct from 'authenticated'
     and coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::json->>'role'
         is distinct from 'anon';
$$;
revoke all on function public.rpc_caller_trusted() from public, anon, authenticated;
grant execute on function public.rpc_caller_trusted() to service_role;


-- get_active_event: room = p_room_id
alter function public.get_active_event(p_room_id uuid) rename to get_active_event__inner;
revoke all on function public.get_active_event__inner(p_room_id uuid) from public, anon, authenticated;
create function public.get_active_event(p_room_id uuid)
returns TABLE(id uuid, room_id uuid, name text, played_at timestamp with time zone, created_at timestamp with time zone, host_note text, pack_slug text, settled_at timestamp with time zone, max_seats integer, pack_slugs text[]) language plpgsql stable security definer set search_path = '' as $fn$
begin
  if not (public.rpc_caller_trusted() or public.is_room_member(p_room_id, public.current_user_id())) then
    return;
  end if;
  return query select * from public.get_active_event__inner(p_room_id);
end;
$fn$;
revoke all on function public.get_active_event(p_room_id uuid) from public, anon;
grant execute on function public.get_active_event(p_room_id uuid) to authenticated, service_role;

