-- get_casino_config: room = p_room_id
alter function public.get_casino_config(p_room_id uuid) rename to get_casino_config__inner;
revoke all on function public.get_casino_config__inner(p_room_id uuid) from public, anon, authenticated;
create function public.get_casino_config(p_room_id uuid)
returns TABLE(room_id uuid, enabled boolean, chip_color_map jsonb, standard_presets boolean, vision_provider text, vision_model text, vision_api_key text) language plpgsql stable security definer set search_path = '' as $fn$
begin
  if not (public.rpc_caller_trusted() or public.is_room_member(p_room_id, public.current_user_id())) then
    return;
  end if;
  return query select c.room_id, c.enabled, c.chip_color_map, c.standard_presets,
    c.vision_provider, c.vision_model,
    case when public.rpc_caller_trusted() or public.is_room_host(c.room_id, public.current_user_id())
         then c.vision_api_key end
    from public.get_casino_config__inner(p_room_id) c;
end;
$fn$;
revoke all on function public.get_casino_config(p_room_id uuid) from public, anon;
grant execute on function public.get_casino_config(p_room_id uuid) to authenticated, service_role;

