-- get_withdrawal_balance: room = (select e.room_id from public.events e where e.id = p_event_id)
alter function public.get_withdrawal_balance(p_event_id uuid, p_user_id uuid) rename to get_withdrawal_balance__inner;
revoke all on function public.get_withdrawal_balance__inner(p_event_id uuid, p_user_id uuid) from public, anon, authenticated;
create function public.get_withdrawal_balance(p_event_id uuid, p_user_id uuid)
returns bigint language plpgsql stable security definer set search_path = '' as $fn$
begin
  if not (public.rpc_caller_trusted() or public.is_room_member((select e.room_id from public.events e where e.id = p_event_id), public.current_user_id())) then
    return null;
  end if;
  return public.get_withdrawal_balance__inner(p_event_id, p_user_id);
end;
$fn$;
revoke all on function public.get_withdrawal_balance(p_event_id uuid, p_user_id uuid) from public, anon;
grant execute on function public.get_withdrawal_balance(p_event_id uuid, p_user_id uuid) to authenticated, service_role;

-- report_calendar_identifier: room = (select e.room_id from public.events e where e.id = p_event_id)
alter function public.report_calendar_identifier(p_event_id uuid, p_identifier text) rename to report_calendar_identifier__inner;
revoke all on function public.report_calendar_identifier__inner(p_event_id uuid, p_identifier text) from public, anon, authenticated;
create function public.report_calendar_identifier(p_event_id uuid, p_identifier text)
returns void language plpgsql volatile security definer set search_path = '' as $fn$
begin
  if not (public.rpc_caller_trusted() or public.is_room_member((select e.room_id from public.events e where e.id = p_event_id), public.current_user_id())) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;
  perform public.report_calendar_identifier__inner(p_event_id, p_identifier);
end;
$fn$;
revoke all on function public.report_calendar_identifier(p_event_id uuid, p_identifier text) from public, anon;
grant execute on function public.report_calendar_identifier(p_event_id uuid, p_identifier text) to authenticated, service_role;

